seen_ids = set()
for page_index in range(100):
    page = apis.spotify.search_artists(query=genre, genre=genre, min_follower_count=min_fol, page_index=page_index)
    items = [a for a in page if a.artist_id not in seen_ids]
    if not items:
        break
    seen_ids.update(a.artist_id for a in items)
    for artist in items:
        try:
            apis.spotify.follow_artist(access_token=access_token, artist_id=artist.artist_id, raise_on_failure=False)
        except Exception as e:
            # log and continue
            pass

